  ('USW00003927', 'Dallas-Fort Worth International Airport, TX', 'NOAA NCEI 1991-2020 U.S. Climate Normals, Hourly Normals dataset, https://www.ncei.noaa.gov/access/services/data/v1?dataset=normals-hourly&stations=USW00003927'),
  ('USW00012960', 'Houston Bush Intercontinental Airport, TX', 'NOAA NCEI 1991-2020 U.S. Climate Normals, Hourly Normals dataset, https://www.ncei.noaa.gov/access/services/data/v1?dataset=normals-hourly&stations=USW00012960');

